package com.isc.identityreference.persistence.oracle;
import com.isc.identityreference.governance.*; import com.isc.identityreference.persistence.oracle.entity.IdentityAuditEventEntity; import com.isc.identityreference.persistence.oracle.repository.IdentityAuditEventRepository; import java.time.Instant; import java.util.List;
public final class OracleAuditEventStore implements AuditEventStore { private final IdentityAuditEventRepository repo; public OracleAuditEventStore(IdentityAuditEventRepository r){repo=r;} public void append(AuditEvent e){var x=new IdentityAuditEventEntity();x.setEventId(e.eventId().toString());x.setLookupKeyHash(e.lookupKeyHash());x.setEventType(e.eventType());x.setActorType(e.actorType());x.setReasonCode(e.reasonCode());x.setProviderId(e.providerId());x.setPolicyVersion(e.policyVersion());x.setFromState(e.fromState());x.setToState(e.toState());x.setOperationId(e.operationId()==null?null:e.operationId().toString());x.setOccurredAt(e.occurredAt());repo.save(x);} public int purgeBefore(Instant c,int limit){var rows=repo.findByOccurredAtBeforeOrderByOccurredAtAsc(c,org.springframework.data.domain.PageRequest.of(0,limit));if(rows.isEmpty())return 0;repo.deleteAllByIdInBatch(rows.stream().map(IdentityAuditEventEntity::getEventId).toList());return rows.size();} public List<AuditEvent> recent(int limit){return repo.findAll(org.springframework.data.domain.PageRequest.of(0,limit,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"occurredAt"))).stream().map(x->new AuditEvent(java.util.UUID.fromString(x.getEventId()),x.getLookupKeyHash(),x.getEventType(),x.getActorType(),x.getReasonCode(),x.getProviderId(),x.getPolicyVersion(),x.getFromState(),x.getToState(),x.getOperationId()==null?null:java.util.UUID.fromString(x.getOperationId()),x.getOccurredAt())).toList();} }
